+        let table = odd_multiples(self).map(CachedPoint::from_projective);
+
+        let naf = wnaf5(&scalar);
+        let mut out = Self::IDENTITY;
+
+        for &digit in naf.iter().rev() {
+            out = out.double();
+            if digit > 0 {
+                out = out.add_cached(table[(digit >> 1) as usize]);
+            } else if digit < 0 {
