+    #[inline]
+    fn add_cached(self, rhs: CachedPoint) -> Self {
+        if self.is_identity() {
+            return Self {
+                x: rhs.x,
+                y: rhs.y,
+                z: rhs.z,
+            };
+        }
+        if rhs.z.is_zero() {
+            return self;
+        }
+
+        let z1z1 = self.z.square();
+        let u1 = self.x * rhs.zz;
+        let u2 = rhs.x * z1z1;
+        let s1 = self.y * rhs.zzz;
+        let s2 = rhs.y * self.z * z1z1;
+        let h = u2 - u1;
+        let slope_num = s2 - s1;
+
+        if h.is_zero() {
+            return if slope_num.is_zero() {
+                self.double()
+            } else {
+                Self::IDENTITY
+            };
+        }
+
+        let hh = h.square();
+        let hhh = h * hh;
+        let v = u1 * hh;
+        let x = slope_num.square() - hhh - double(v);
+        let y = slope_num * (v - x) - s1 * hhh;
+        let z = self.z * rhs.z * h;
+
+        Self { x, y, z }
+    }

